The output order is `Z3 Z2 Z1 Z0`. Only the selected output is high. The testbench applies all four inputs and checks the one-hot output after each transition.

| A1 A0 | Z3 Z2 Z1 Z0 |
|---|---|
| 00 | 0001 |
| 01 | 0010 |
| 10 | 0100 |
| 11 | 1000 |

```vhdl
library ieee;
use ieee.std_logic_1164.all;

entity decoder2to4 is
    port (
        a : in  std_logic_vector(1 downto 0);
        z : out std_logic_vector(3 downto 0)
    );
end entity decoder2to4;

architecture exm1 of decoder2to4 is
begin
    z <= "0001" when a = "00" else
         "0010" when a = "01" else
         "0100" when a = "10" else
         "1000" when a = "11" else
         "XXXX";
end architecture exm1;

library ieee;
use ieee.std_logic_1164.all;

entity test_decoder2to4 is
end entity test_decoder2to4;

architecture io of test_decoder2to4 is
    signal ain  : std_logic_vector(1 downto 0);
    signal zout : std_logic_vector(3 downto 0);
begin
    dut : entity work.decoder2to4(exm1)
        port map (a => ain, z => zout);

    ain <= "00", "01" after 150 ns, "10" after 300 ns, "11" after 450 ns;

    check_output : process
    begin
        wait for 1 ns;
        assert zout = "0001" report "Failed for input 00" severity failure;
        wait for 150 ns;
        assert zout = "0010" report "Failed for input 01" severity failure;
        wait for 150 ns;
        assert zout = "0100" report "Failed for input 10" severity failure;
        wait for 150 ns;
        assert zout = "1000" report "Failed for input 11" severity failure;
        wait;
    end process;
end architecture io;
```

Use the note's `BIT` ports and concurrent `or` assignment. A separate testbench instantiates the gate and checks `00`, `01`, `10`, and `11`.

```vhdl
entity or21 is
    port (x, y : in bit; z : out bit);
end entity or21;

architecture exm1 of or21 is
begin
    z <= x or y;
end architecture exm1;

entity tb_or21 is
end entity tb_or21;

architecture io of tb_or21 is
    signal a, b, c : bit;
begin
    dut : entity work.or21(exm1)
        port map (x => a, y => b, z => c);

    stimulus : process
    begin
        a <= '0'; b <= '0'; wait for 10 ns;
        assert c = '0' report "OR failed for 00" severity failure;
        a <= '0'; b <= '1'; wait for 10 ns;
        assert c = '1' report "OR failed for 01" severity failure;
        a <= '1'; b <= '0'; wait for 10 ns;
        assert c = '1' report "OR failed for 10" severity failure;
        a <= '1'; b <= '1'; wait for 10 ns;
        assert c = '1' report "OR failed for 11" severity failure;
        wait;
    end process;
end architecture io;
```

Assume eight active-high LEDs on `PORTA` (Mega D22–D29) with series resistors, and a maintained switch on `PC0` (D37) connected to 5 V when closed and held low by an external pull-down when open. Read `PINC` each loop. At HIGH, `0x55` lights PA0, PA2, PA4 and PA6. At LOW, all eight alternate on and off every 500 ms. The nonblocking timer lets the switch be read continuously.

```cpp
#include <Arduino.h>

constexpr uint8_t switchMask = _BV(PC0);
constexpr unsigned long halfPeriodMs = 500;

void setup() {
    PORTA = 0;
    DDRA = 0xFF;
    DDRC &= ~switchMask;
    PORTC &= ~switchMask;
}

void loop() {
    const uint8_t allBlink = ((millis() / halfPeriodMs) & 1U) ? 0xFF : 0x00;
    PORTA = (PINC & switchMask) ? 0x55 : allBlink;
}
```

Assume input on ADC0 (PF0/A0), AVCC measured at 5 V as reference, and a 16 MHz Mega 2560. With division by 128 the ADC clock is 125 kHz. Use the right-adjusted ten-bit result. The ideal halfway code is $2.5\times1024/5=512$. Output `'L'` below 512 and `'H'` at or above it. Accuracy at the boundary depends on the reference and ADC tolerance.

```cpp
#include <Arduino.h>

constexpr uint8_t adcControl = _BV(ADEN) | _BV(ADPS2) | _BV(ADPS1) | _BV(ADPS0);

void setup() {
    PORTA = 0;
    DDRA = 0xFF;
    DDRF &= ~_BV(PF0);
    PORTF &= ~_BV(PF0);
    DIDR0 |= _BV(ADC0D);
    ADCSRB = 0;
    ADMUX = _BV(REFS0);
    ADCSRA = adcControl | _BV(ADIF);
}

void loop() {
    ADCSRA = adcControl | _BV(ADSC);
    while (!(ADCSRA & _BV(ADIF))) {}
    const uint16_t sample = ADC;           // ADCL then ADCH
    ADCSRA = adcControl | _BV(ADIF);       // Write one to clear the flag.
    PORTA = (sample < 512) ? 'L' : 'H';
}
```

Configure all of port B as input and PC0 (Mega D37) as output. Sample `PINB` once per byte. Send the least significant bit first, as in the note's parallel-to-serial example. Assume the receiver agrees on the bit interval and byte boundary. This is raw clocked-by-agreement data, with no UART framing. On a Mega 2560, PB0 through PB7 map to D53, D52, D51, D50, D10, D11, D12 and D13 respectively. Use a source that drives all eight inputs and shares ground.

```cpp
#include <Arduino.h>

constexpr uint8_t serialMask = _BV(PC0);
constexpr unsigned bitTimeUs = 1000;

void setup() {
    DDRB = 0;
    PORTB = 0;              // Input source drives all bits.
    PORTC &= ~serialMask;
    DDRC |= serialMask;
}

void loop() {
    uint8_t value = PINB;
    for (uint8_t bit = 0; bit < 8; ++bit) {
        if (value & 1U) PORTC |= serialMask;
        else PORTC &= ~serialMask;
        delayMicroseconds(bitTimeUs);
        value >>= 1;
    }
}
```

Assume a 16 MHz Mega 2560 and use PA4 (D26) as the pulse output. At 4 Hz the period is 250 ms and 60% duty requires 150 ms high and 100 ms low. Use Timer3 CTC with a 1 ms time base. At prescaler 64 the timer tick is 4 µs, so $\mathrm{OCR3A}=1000/4-1=249$. The compare-A ISR counts 150 ticks high and 100 low. This adapts the notes' Timer3 CTC and interrupt examples.

```cpp
#include <Arduino.h>
#include <avr/interrupt.h>

constexpr uint8_t outputMask = _BV(PA4);

ISR(TIMER3_COMPA_vect) {
    static uint8_t phaseMs = 0;
    if (++phaseMs == 150) {
        PORTA &= ~outputMask;
    } else if (phaseMs == 250) {
        phaseMs = 0;
        PORTA |= outputMask;
    }
}

void setup() {
    cli();
    TCCR3B = 0;
    TCCR3A = 0;
    TCNT3 = 0;
    OCR3A = 249;
    TIFR3 = _BV(OCF3A);
    TIMSK3 = _BV(OCIE3A);
    DDRA |= outputMask;
    PORTA |= outputMask;
    TCCR3B = _BV(WGM32) | _BV(CS31) | _BV(CS30);
    sei();
}

void loop() {}
```

Assume 16 MHz, 5 V AVCC reference, analog input ADC1 on PF1/A1, and an active-high LED at PB7 (D13). Use a 128 divider for the 125 kHz ADC clock. Set `ADLAR` so `ADCH` provides the top eight bits, which fit `PORTA`. The note starts a new conversion inside each ISR. This version adapts it to free-running auto-triggering so the next conversion starts automatically. The ADC ISR copies `ADCH`; the main loop changes the LED every 5 ms for a 100 Hz on/off cycle. No ADC polling delays the foreground task.

```cpp
#include <Arduino.h>
#include <avr/interrupt.h>

constexpr uint8_t ledMask = _BV(PB7);
static unsigned long lastLedToggle;

ISR(ADC_vect) {
    PORTA = ADCH;
}

void setup() {
    cli();
    PORTA = 0;
    DDRA = 0xFF;
    PORTB &= ~ledMask;
    DDRB |= ledMask;
    DDRF &= ~_BV(PF1);
    PORTF &= ~_BV(PF1);
    DIDR0 |= _BV(ADC1D);

    ADCSRA = 0;
    ADCSRB = 0;  // MUX5 = 0 and ADTS = 000 (free running)
    ADMUX = _BV(REFS0) | _BV(ADLAR) | _BV(MUX0);
    ADCSRA = _BV(ADEN) | _BV(ADATE) | _BV(ADIE) | _BV(ADIF)
           | _BV(ADPS2) | _BV(ADPS1) | _BV(ADPS0);
    ADCSRA |= _BV(ADSC);
    sei();
    lastLedToggle = micros();
}

void loop() {
    if (micros() - lastLedToggle >= 5000UL) {
        lastLedToggle += 5000UL;
        PINB = ledMask;
    }
}
```

Assume a 16 MHz ATmega2560, a low-voltage isolated detector whose output is high on supply failure, and an independent supply for the MCU and buzzer. The exam specifies the MCU port pins. On an Arduino Mega 2560, `PD7` is D38, `PD0` is D21 and `PB0` is D53. PD0 is the MCU port name and does not mean Arduino digital pin 0.

```text
PD7 → gate resistor → low-side MOSFET driver → motor field winding
      Put a flyback diode across the winding, cathode to its positive rail.
Isolated failure detector → PD0         PB0 → active-low buzzer input
```

The pulse period is 50 ms, with 40 ms high and 10 ms low. Timer1 CTC at division by 64 gives a 4 µs tick. Set `OCR1A = 249` for a 1 ms compare interrupt. The ISR generates the pulse on the specified GPIO. The main loop reads `PIND` and continuously drives the alarm. Neither the winding nor mains goes directly to a GPIO. Use a suitable separate driver if the buzzer input exceeds GPIO ratings.

```cpp
#include <Arduino.h>
#include <avr/interrupt.h>

constexpr uint8_t fieldMask = _BV(PD7);
constexpr uint8_t failureMask = _BV(PD0);
constexpr uint8_t buzzerMask = _BV(PB0);

ISR(TIMER1_COMPA_vect) {
    static uint8_t phaseMs = 0;
    if (++phaseMs == 40) {
        PORTD &= ~fieldMask;
    } else if (phaseMs == 50) {
        phaseMs = 0;
        PORTD |= fieldMask;
    }
}

void setup() {
    cli();
    DDRD &= ~failureMask;
    PORTD &= ~failureMask;       // Detector actively drives PD0.
    PORTB |= buzzerMask;        // Alarm off before enabling output.
    DDRB |= buzzerMask;

    TCCR1B = 0;
    TCCR1A = 0;
    TCNT1 = 0;
    OCR1A = 249;
    TIFR1 = _BV(OCF1A);
    TIMSK1 = _BV(OCIE1A);
    DDRD |= fieldMask;
    PORTD |= fieldMask;
    TCCR1B = _BV(WGM12) | _BV(CS11) | _BV(CS10);
    sei();
}

void loop() {
    if (PIND & failureMask) PORTB &= ~buzzerMask;
    else PORTB |= buzzerMask;
}
```

The notes supply the timer and GPIO techniques. The motor driver, isolated detector and alarm supply are circuit assumptions added for the exam scenario.
